SELECT b.*, bd.question_text, bd.user_answer, bd.ai_feedback as ai_assessment, bd.damage, bd.difficulty, bd.keyword_tags, s.title as stage_title, s.job_category FROM battle_bookmark b LEFT JOIN battle_detail bd ON b.ref_battle_id = bd.battle_id AND b.ref_detail_id = bd.detail_id AND b.user_id = bd.user_id LEFT JOIN battle bt ON b.ref_battle_id = bt.battle_id AND b.user_id = bt.user_id LEFT JOIN stage s ON bt.stage_id = s.stage_id WHERE b.user_id = #{userId}
AND s.job_category = #{category}
AND (bd.question_text LIKE CONCAT('%', #{search}, '%') OR b.memo LIKE CONCAT('%', #{search}, '%'))
ORDER BY b.created_at DESC
ORDER BY b.created_at ASC
ORDER BY b.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM battle_bookmark b LEFT JOIN battle_detail bd ON b.ref_battle_id = bd.battle_id AND b.ref_detail_id = bd.detail_id AND b.user_id = bd.user_id LEFT JOIN battle bt ON b.ref_battle_id = bt.battle_id AND b.user_id = bt.user_id LEFT JOIN stage s ON bt.stage_id = s.stage_id WHERE b.user_id = #{userId}
AND s.job_category = #{category}
